  ["不能跳"] = "Không Thể Nhảy",
  ["不要乱扔秘偶，会被追踪的。"] = "Đừng ném Bí Ngẫu lung tung, sẽ bị truy dấu.",
  ["不要再打啦"] = "Đừng Đánh Nữa!",
