  ["丰饶污染"] = "Ô Nhiễm Phong Nhiêu",
  ["丰饶污染让你受到的伤害提高100%，最多叠加3层"] = "Ô Nhiễm Phong Nhiêu khiến sát thương bạn phải chịu tăng 100%, cộng dồn tối đa 3 tầng.",
  ["临时属性buff"] = "Buff Thuộc Tính Tạm Thời",
  ["临时测试_攻速200%"] = "Kiểm Thử Tạm_Tốc Đánh 200%",
  ["临时测试用"] = "Dùng thử tạm thời.",
  ["临时背包"] = "Túi Tạm",
