  ["厄运布偶"] = "Búp Bê Xui Xẻo",
  ["厄运缠身"] = "Ách Vận Quấn Thân",
  ["历史之涌"] = "Lịch Sử Chi Dũng",
  ["历史冲击"] = "Xung Kích Lịch Sử",
  ["历史悠久的日记"] = "Nhật Ký Lâu Đời",
  ["历史投影的微弱回响，记录着封印物曾经的力量碎片。用它唤醒沉睡的投影，让危险逐渐显露真容。"] = "Tiếng vọng yếu ớt của Hình Chiếu Lịch Sử, ghi lại mảnh sức mạnh Vật Phong Ấn từng sở hữu. Dùng nó đánh thức hình chiếu đang ngủ, để nguy hiểm dần lộ nguyên hình.",
  ["历史旋涡"] = "Vòng Xoáy Lịch Sử",
  ["历史旋涡存在特效"] = "Xoáy Lịch Sử-Hiệu Ứng Tồn Tại",
  ["历史明灯"] = "Minh Đăng Lịch Sử",
  ["历史最佳"] = "Tốt Nhất Lịch Sử",
  ["历史荣誉"] = "Vinh Dự Lịch Sử",
  ["历史词条 %s"] = "Dòng Thuộc Tính Lịch Sử %s",
  ["历史词条来源于重塑过的最强非凡词条."] = "Dòng Lịch Sử lấy từ dòng Phi Phàm mạnh nhất từng nhận khi Tái Tạo.",
  ["历史长河中凝固的真实碎片，蕴含着封印物本体的部分本质。使用它将使投影无限接近真实，代价是危险也将随之降临。"] = "Mảnh chân thực đông cứng trong dòng sông lịch sử, chứa một phần bản chất của Vật Phong Ấn. Dùng nó sẽ khiến hình chiếu tiến gần vô hạn tới chân thực; cái giá là nguy hiểm cũng theo đó giáng xuống.",
  ["历史预测记录"] = "Lịch Sử Dự Đoán",
  ["历届排行"] = "Xếp Hạng Các Kỳ Trước",
  ["历届排行榜"] = "BXH Các Kỳ Trước",
  ["压制"] = "Áp Chế",
  ["压制·首领"] = "Áp Chế Boss",
  ["压制攻击"] = "Công Kích Áp Chế",
  ["压暗"] = "Làm Tối",
  ["压暗后处理"] = "Hậu Xử Lý Làm Tối",
  ["厚重的金边方框眼镜，让人联想起大学图书馆严肃而规矩的档案管理员。"] = "Kính vuông viền vàng dày khiến người ta liên tưởng tới vị quản lý hồ sơ nghiêm túc, quy củ trong thư viện đại học.",
  ["原初之仪"] = "Nghi Thức Nguyên Sơ",
  ["原地坐下"] = "Ngồi xuống tại chỗ",
  ["原地头疼"] = "Đau Đầu Tại Chỗ",
  ["原地头疼结束"] = "Đau Đầu Tại Chỗ-Kết Thúc",
  ["原地蓄力，对目标进行一次冲撞，冲撞后会跃起用大盾砸地，发出震荡波\n造成一次冲撞伤害，跃起前有预警，造成一次圆形范围伤害"] = "Tụ lực tại chỗ rồi húc mục tiêu một lần; sau cú húc sẽ nhảy lên, dùng đại khiên đập xuống đất tạo sóng chấn động.\nGây 1 lần sát thương húc; trước khi nhảy có cảnh báo, sau đó gây 1 lần sát thương phạm vi tròn.",
  ["原始嚎叫"] = "Gầm Thét Nguyên Thủy",
  ["原始月亮"] = "Mặt Trăng Nguyên Thủy",
  ["原始爆发"] = "Bộc Phát Nguyên Thủy",
