  ["开始1v1决斗"] = "Bắt Đầu Quyết Đấu 1v1",
  ["开始关注你了"] = "Đã Bắt Đầu Theo Dõi Bạn",
  ["开始报名"] = "Mở Đăng Ký",
  ["开始时间"] = "Thời Gian Bắt Đầu",
  ["开始晋升任务"] = "Bắt Đầu Nhiệm Vụ Thăng Tiến",
