  ["持续时间"] = "Thời Gian Duy Trì",
  ["持续时间内受到伤害则减少目标攻击力。"] = "Trong thời gian hiệu lực, mỗi khi chịu sát thương sẽ giảm Tấn Công của mục tiêu.",
  ["持续时间内目标受到的治疗量增加5%。"] = "Trong thời gian hiệu lực, lượng trị liệu mục tiêu nhận được tăng 5%.",
  ["持续期间不能通过界面按钮自主复活，不能被友方复活，作为奶妈不能自活（可以被烧尸体）"] = "Trong thời gian hiệu lực không thể tự hồi sinh bằng nút giao diện, không thể được đồng minh hồi sinh; nếu là healer cũng không thể tự hồi sinh (có thể bị thiêu thi thể).",
  ["持续治疗"] = "Trị Liệu Liên Tục",
  ["持续治疗周身范围内友方，每1.5秒回复友方*d点生命，上限7次。技能生效期间自身可以移动、释放其它技能。"] = "Liên tục trị liệu đồng minh trong phạm vi xung quanh; mỗi 1.5 giây hồi *d Máu cho đồng minh, tối đa 7 lần. Trong lúc kỹ năng có hiệu lực, bản thân có thể di chuyển và dùng kỹ năng khác.",
  ["持续治疗周身范围内友方，每1.5秒回复范围内友方*d点生命，上限7次。技能生效期间自身可以移动、释放其它技能。\n仅<HighLight>空想姿态</>可用，<HighLight>噩梦姿态</>下切换为<HighLight>心灵之火</>。"] = "Liên tục trị liệu đồng minh trong phạm vi xung quanh; mỗi 1.5 giây hồi *d Máu cho đồng minh trong phạm vi, tối đa 7 lần. Trong lúc kỹ năng có hiệu lực, bản thân có thể di chuyển và dùng kỹ năng khác. Chỉ dùng được trong <HighLight>Tư Thế Không Tưởng</>; ở <HighLight>Tư Thế Ác Mộng</> sẽ đổi thành <HighLight>Linh Hoả</>.",
  ["持续点击按钮，消除队友滞涩状态。"] = "Liên tục nhấn nút để xóa trạng thái Trì Trệ của đồng đội.",
  ["持续点击按钮，解除滞涩状态。"] = "Liên tục nhấn nút để giải trừ trạng thái Trì Trệ.",
  ["持续百分比伤害"] = "Sát Thương % Liên Tục",
  ["持续给目标维持法术场"] = "Liên tục duy trì Trường Pháp Thuật trên mục tiêu.",
  ["持续锻炼，塑造超越凡人的体魄。"] = "Không ngừng rèn luyện, tôi luyện thể phách vượt khỏi người thường.",
  ["挂接混乱剑"] = "Gắn Kiếm Hỗn Loạn",
  ["挂接秩序剑"] = "Gắn Kiếm Trật Tự",
  ["指定目标范围释放指定技能"] = "Thi triển kỹ năng chỉ định trong phạm vi mục tiêu chỉ định.",
  ["指尖流转的温柔，将每一次触碰化作令人沉醉的时光。"] = "Sự dịu dàng lướt qua đầu ngón tay, biến mỗi lần chạm thành khoảnh khắc khiến người ta say mê.",
  ["指尖轻轻一扬，便在人群里打捞出一个老熟人。"] = "Đầu ngón tay khẽ nhấc, đã “vớt” được một người quen cũ giữa đám đông.",
  ["指尖轻轻一点，还原最不加粉饰的面颊。"] = "Đầu ngón tay khẽ chạm, trả lại gương mặt mộc không tô điểm.",
  ["指挥"] = "Chỉ Huy",
  ["指挥策略"] = "Chiến Lược Chỉ Huy",
  ["指挥面板"] = "Bảng Chỉ Huy",
  ["指派完成后点击<Highlight>开始建造</>进行建造。"] = "Sau khi phân công, nhấn <Highlight>Bắt Đầu Xây</> để xây dựng.",
  ["指派更多的秘偶可以<Highlight>缩短建造时长</>。"] = "Phân công thêm Bí Ngẫu có thể <Highlight>rút ngắn thời gian xây</>.",
  ["指针亮光标记"] = "Đánh Dấu Ánh Sáng Kim Chỉ",
  ["指针标记"] = "Đánh Dấu Kim Chỉ",
  ["指针隐身怪标记"] = "Kim Chỉ-Đánh Dấu Quái Ẩn Thân",
  ["按 <img id=\"KeyPrompt_W\" width=\"33\" height=\"38\"/> 向前移动"] = "Nhấn <img id=\"KeyPrompt_W\" width=\"33\" height=\"38\"/> để tiến lên",
  ["按下 <img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>洞察</>、<img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>心灵之火</>、<img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>梦境编织</>、<img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>狂乱</> 完成连招"] = "Nhấn <img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>Động Sát</>, <img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>Linh Hoả</>, <img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>Dệt Mộng</>, <img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>Cuồng Loạn</> để hoàn thành combo",
  ["按下 <img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>放逐</>、<img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>星云咏叹</>、<img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>戏法演绎</>、<img id=\"KeyPrompt_4\" width=\"33\" height=\"38\"/> <Orange>灵界穿梭</>、<img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>层叠之门</> 完成连招"] = "Nhấn <img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>Phóng Trục</>, <img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>Thán Vân</>, <img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>Ảo Thuật</>, <img id=\"KeyPrompt_4\" width=\"33\" height=\"38\"/> <Orange>Xuyên Giới</>, <img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>Trùng Môn</> để hoàn thành combo",
  ["按下 <img id=\"KeyPrompt_4\" width=\"33\" height=\"38\"/> <Orange>愚者祝福</>、<img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>空气子弹</>、<img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>塔罗牌阵</>、<img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>奇迹牌雨</>、<img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>灵性爆发</> 完成连招"] = "Nhấn <img id=\"KeyPrompt_4\" width=\"33\" height=\"38\"/> <Orange>Ngu Phúc</>, <img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>Đạn Khí</>, <img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>Trận Tarot</>, <img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>Mưa Bài</>, <img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>Linh Bạo</> để hoàn thành combo",
  ["按下 <img id=\"KeyPrompt_4\" width=\"33\" height=\"38\"/> <Orange>皇帝的新衣</>、<img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>知识逐人</>、<img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>光之折射</>、<img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>星沙</>、<img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>信息洪流</> 完成连招"] = "Nhấn <img id=\"KeyPrompt_4\" width=\"33\" height=\"38\"/> <Orange>Hoàng Y</>, <img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>Trí Nhân</>, <img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>Quang Khúc</>, <img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>Tinh Sa</>, <img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>Tin Tuyến</> để hoàn thành combo",
  ["按下 <img id=\"KeyPrompt_4\" width=\"33\" height=\"38\"/> <Orange>荣耀之斩</>、<img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>猎魔瞬斩</>、<img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>怒意猛击</>、<img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>日暮飓风</>、<img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>光之风暴</> 完成连招"] = "Nhấn <img id=\"KeyPrompt_4\" width=\"33\" height=\"38\"/> <Orange>Quang Trảm</>, <img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>Liệp Ma Trảm</>, <img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>Nộ Ý Kích</>, <img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>Cuồng Phong</>, <img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>Quang Bạo</> để hoàn thành combo",
  ["按下 <img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>秩序审判</>、<img id=\"KeyPrompt_4\" width=\"33\" height=\"38\"/> <Orange>太阳誓约</>、<img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>飓风斧</>、<img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>净化之斩</>、<img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>惩戒</> 完成连招"] = "Nhấn <img id=\"KeyPrompt_Q\" width=\"33\" height=\"38\"/> <Orange>Phán Xét</>, <img id=\"KeyPrompt_4\" width=\"33\" height=\"38\"/> <Orange>Nhật Thệ</>, <img id=\"KeyPrompt_3\" width=\"33\" height=\"38\"/> <Orange>Cuồng Phủ</>, <img id=\"KeyPrompt_1\" width=\"33\" height=\"38\"/> <Orange>Tịnh Trảm</>, <img id=\"KeyPrompt_2\" width=\"33\" height=\"38\"/> <Orange>Trừng Phạt</> để hoàn thành combo",
  ["按下 <img id=\"KeyPrompt_W\" width=\"33\" height=\"38\"/><img id=\"KeyPrompt_A\" width=\"33\" height=\"38\"/><img id=\"KeyPrompt_S\" width=\"33\" height=\"38\"/><img id=\"KeyPrompt_D\" width=\"33\" height=\"38\"/> 移动"] = "Nhấn <img id=\"KeyPrompt_W\" width=\"33\" height=\"38\"/><img id=\"KeyPrompt_A\" width=\"33\" height=\"38\"/><img id=\"KeyPrompt_S\" width=\"33\" height=\"38\"/><img id=\"KeyPrompt_D\" width=\"33\" height=\"38\"/> để di chuyển",
  ["按住 <img id=\"KeyPrompt_LeftMouseButton\" width=\"33\" height=\"41\"/> 圈出想要生成建筑的<Highlight>区域</>。"] = "Giữ <img id=\"KeyPrompt_LeftMouseButton\" width=\"33\" height=\"41\"/> để khoanh <Highlight>khu vực</> muốn tạo công trình.",
  ["按住鼠标调整视角:"] = "Giữ Chuột Để Điều Chỉnh Góc Nhìn:",
  ["按强化蔓袭子技能/区域表现定位为区域输出。"] = "Theo định vị của kỹ năng con/biểu hiện vùng của Cường Hóa Dây Leo Tập Kích, đây là Sát Thương Khu Vực.",
  ["挑战"] = "Thử Thách",
  ["挑战下层"] = "Thử Thách Tầng Dưới",
  ["挑战不可能，哪怕最终的结果只是虚假的。"] = "Thách thức điều bất khả thi, cho dù kết quả cuối cùng chỉ là giả tạo.",
  ["挑战失败！倒计时5秒，重新开始波次！"] = "Thử thách thất bại! Còn 5 giây, Làn Sóng sẽ bắt đầu lại!",
  ["挑战线路"] = "Tuyến Thử Thách",
  ["挑衅"] = "Khiêu Khích",
  ["挚友特权"] = "Đặc Quyền Bạn Thân",
  ["挣脱"] = "Thoát Trói",
  ["挥击"] = "Vung Kích",
  ["挥动大锤"] = "Vung Đại Chùy",
  ["挥动蛛肢绞杀前方敌人，对2格扇形范围敌人造成<color=red>220%攻击力伤害</color>。"] = "Vung chi nhện siết giết kẻ địch phía trước, gây <color=red>220% Sát Thương Công Kích</color> lên kẻ địch trong vùng quạt 2 ô.",
  ["挥斧造成<HighLight>160%</>攻击伤害，使敌人防御降低<HighLight>15</>点，持续<HighLight>5</>秒；自身攻速提高<HighLight>20%</>，持续4秒。"] = "Vung rìu gây <HighLight>160%</> Sát Thương Tấn Công, giảm <HighLight>15</> Phòng Thủ của kẻ địch trong <HighLight>5</> giây; Tốc Độ Đánh bản thân tăng <HighLight>20%</> trong 4 giây.",
  ["挥砍"] = "Vung Chém",
  ["挥砍人型模版怪始终持有武器"] = "Quái Mẫu Hình Người Chém-Luôn Cầm Vũ Khí",
  ["挥臂重砸"] = "Vung Tay Trọng Tạp",
  ["挥舞双剑发动暴风骤雨般的攻势造成大量伤害，以连续的挥砍控制敌人，自身获得黄昏印记（用于强化怒意猛击和终结技能）。输出形态下附加衰败（持续造成伤害）。"] = "Vung song kiếm tung thế công như mưa bão, gây lượng lớn sát thương và dùng chuỗi chém liên tục khống chế kẻ địch; bản thân nhận Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu). Tư Thế Tấn Công thêm Suy Bại (liên tục gây sát thương).",
  ["挥舞巨剑以雷霆之势向左右连续挥砍，随后向前方猛力下劈，造成伤害并获得一枚黄昏印记（用于强化怒意猛击和终结技能）。"] = "Vung cự kiếm như lôi đình liên tục chém trái phải, sau đó bổ mạnh về phía trước, gây sát thương và nhận 1 Dấu Ấn Hoàng Hôn (dùng để cường hóa Nộ Ý Kích và Kỹ Năng Kết Liễu).",
  ["挥镰造成<HighLight>180%</>攻击伤害；生命不高于35%的敌人额外受到<HighLight>50%</>攻击伤害；自身获得<HighLight>10%</>护盾。"] = "Vung liềm gây <HighLight>180%</> Sát Thương Tấn Công; kẻ địch có Máu không quá 35% chịu thêm <HighLight>50%</> Sát Thương Tấn Công; bản thân nhận <HighLight>10%</> Khiên.",
  ["挫折命运"] = "Vận Mệnh Trắc Trở",
  ["振刀-碎屏"] = "Chấn Đao-Vỡ Màn Hình",
  ["振刀-碎屏-不带闪光"] = "Chấn Đao-Vỡ Màn Hình-Không Có Chớp Sáng",
  ["振刀预警圈"] = "Vòng Cảnh Báo Phản Đòn",
  ["挺直的脊背，让自信的你更值得信赖。"] = "Lưng thẳng khiến một bạn đầy tự tin càng đáng tin cậy hơn.",
  ["捆绑禁锢锁血"] = "Trói-Trói Buộc-Khóa Máu",
  ["捏脸导入"] = "Nhập Khuôn Mặt",
